return {
    ["%Y年%m月%d日 %H：%M"] = "%Y Year %m Month %d Day %H:%M",
    ["1-显示, 0-隐藏；x1,y1 左上角坐标；x2,y2 右下角坐标;如1,100,100,1024,1024"] = "1: Show, 0: Hide; x1, y1 top-left coordinates; x2, y2 bottom-right; e.g., 1, 100, 100, 1024, 1024.",
    ["<Assistant_Title1>战斗新手·三</>\n<Assistant_Title2>成就分类：</>养成-成长\n<Assistant_Title2>解锁条件：</>任意技能达到15级"] = "<Assistant_Title1>Combat Novice · III</>\n<Assistant_Title2>Achievement Category: </>Growth - Development\n<Assistant_Title2>Unlock Condition: </>Any Skill reaches Level 15",
    ["<DecH>工艺：</>蓝白蕾丝\n即便是误入的来客，也请遵从着装的礼仪。换上蓝白蕾丝的俏皮礼服，加入怪诞奇妙的茶会。"] = "<DecH>Craftsmanship: </>Blue-White Lace\nEven if you are an unexpected guest, please observe the etiquette of dress. Put on the playful blue-white lace dress and join the whimsical tea party.",
    ["<HighLight>致迷途的羔羊与渴求庇护的灵魂</>：\n能占用一下您的时间吗？我想给您讲一讲我们的道标和救主，“愚者”先生。\n我主自称愚者，在过去，在现在，也在未来，他是支配灵界的伟大主宰，也是执掌好运的黄黑之王，更是每个生灵追求永恒的道标。\n他是怜悯的，他是仁慈的，他是这个世界的救主，他让我们以他来代称，而非祂。\n他的仁爱播撒在人间，为家家户户带去温暖。我们将这关怀化作触手可及的回馈，将愚者的福音传遍大地——\n每月购买愚者福音，您将获得每日返现，以及福音定期馈赠的材料物资。我们还将为您带来每日福音券的抽取，解读运势。\n聆听《愚者圣典》，赞美愚者！赞美愚者的馈赠！愿我主的恩典在您身边日夜相伴，愿这福音成为您前行路上永不熄灭的灯火！"] = "<HighLight>To the lost lambs and souls seeking shelter</>: \nMay I have a moment of your time? I would like to tell you about our beacon and savior, Mr. Fool. \nMy Lord calls himself The Fool. In the past, in the present, and in the future, He is the great ruler who dominates the Spirit World, the King of Yellow and Black who holds good luck, and the beacon for every living creature pursuing eternity. \nHe is compassionate, He is merciful, and He is the savior of this world. He lets us refer to Him as 'him' instead of 'He'. \nHis benevolence is spread across the human world, bringing warmth to every household. We transform this care into tangible rewards, spreading the Gospel of The Fool throughout the land—\nPurchase the Gospel of The Fool every month to receive daily cashbacks, as well as materials and supplies gifted regularly by the Gospel. We will also bring you daily Gospel Ticket draws and fortune readings. \nListen to the 'Scripture of The Fool', praise The Fool! Praise the gifts of The Fool! May the grace of my Lord accompany you day and night, and may this Gospel become the never-extinguishing lamp on your path forward!",
    ["<Highlight>当前狩猎任务已完成</>，叹息回响仍持续回荡，可继续<Highlight>狩猎其它敌人，夺取更多段位胜点</>。\n\n或将已，夺取的<Highlight>猎杀进度</>与<Highlight>猩红遗物</>，呈递给那位自称<Highlight>猎杀管家</>的苍白身影，即可换取<Highlight>属于你的那份非凡馈赠</>。"] = "<Highlight> Current hunting quest completed </>, the echo of sighs still lingers, you can continue to <Highlight> hunt other enemies and seize more rank points </>. \n \n Or, present the seized <Highlight> Hunting Progress </> and <Highlight> Scarlet Relics </> to the pale figure who calls himself the <Highlight> Hunting Butler </> to exchange for <Highlight> that Beyonder gift belonging to you </>.",
    ["<Highlight>窥秘的角落：周一开放</>\n<Highlight>哀嚎黑市：周二/五开放</>\n<Highlight>黄金之罪：周三/六开放</>\n<Highlight>亡者疑踪：周四/日开放</>"] = "<Highlight>A Corner of Mysteries: Opens on Monday</> \n <Highlight> Wailing Black Market: Opens on Tuesday/Friday </> \n <Highlight> Sin of Gold: Opens on Wednesday/Saturday </> \n <Highlight> Traces of the Dead: Opens on Thursday/Sunday </>",
    ["<HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\">火焰跳跃</>一段释放时会在4秒内移动速度提升50%。\n每次受到伤害前获得持续8秒的<HighLight>护盾</>效果和持续4秒的50%加速效果，该效果冷却时长20秒。"] = "Casting the first stage of <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\"> Flame Jump </> increases movement speed by 50% for 4 seconds. \n Gain a <HighLight> Shield </> effect lasting 8 seconds and a 50% Acceleration effect lasting 4 seconds before taking damage; this effect has a 20-second cooldown.",
    ["<P_Heart>(无奈地打开门）</>……好吧，是我。"] = "<P_Heart>(Opens the door helplessly)</>...Alright, it's me.",
    ["<P_Heart>头有点晕晕的…….</>"] = "<P_Heart>My head feels a bit dizzy...</>",
    ["<P_Heart>工人们看起来情绪高昂！</>"] = "<P_Heart>The workers look high-spirited!</>",
    ["SpawnInterval大于0时有效"] = "Valid when SpawnInterval is greater than 0.",
